/* Enemy-only raid definitions: deliberately absent from UNITS, decks and boosters. */
(function(root){'use strict';
const G=root.Game;
const CONFIG={version:1,bossHp:17000,bossAtk:52,bossDefense:20,bossRate:1.5,bossRange:650,sproutHp:400,sproutAtk:34,sproutDefense:12,sproutRate:1.35,sproutSpeed:38,maxLosses:5,rootFirst:6,rootInterval:9,rootWarning:1.5,rootRadius:46,rootDamage:70,rootDuration:1.5,healFirst:12,healInterval:16,healChannel:3,healPerSprout:160,healCap:800,replenishAt:28,maxSprouts:2,attackWindup:.45,attackTravel:.22};
const TREE='raid_ancient_tree',SPROUT='raid_carnivorous_sprout';
for(const [id,name,hp,atk,defense,rate,speed,range]of [[TREE,'Corrupted Ancient Tree',CONFIG.bossHp,CONFIG.bossAtk,CONFIG.bossDefense,CONFIG.bossRate,0,CONFIG.bossRange],[SPROUT,'Carnivorous Sprout',CONFIG.sproutHp,CONFIG.sproutAtk,CONFIG.sproutDefense,CONFIG.sproutRate,CONFIG.sproutSpeed,34]])G.BY[id]={id,name,color:'#ae7ad1',family:id===TREE?'mage':'monster',hp,atk,defense,rate,speed,range,crit:0,area:0,traits:[],kind:'passive',trigger:{kind:'passive',limit:0},ability:'',detail:'',cost:0,enemyOnly:true};
function formation(s){return [{uid:'raid-tree',type:s.raid.bossType||TREE,level:0,pos:12},...(s.round>=2?[1,3].map((pos,i)=>({uid:'raid-sprout-'+i,type:s.raid.minionType||SPROUT,level:0,pos})):[])];}
function build(config,seed,visible){const c=JSON.parse(JSON.stringify(config));c.wins=5;c.difficulty='normal';c.enemy=root.Training.side();const s=root.Training.build(c,seed,visible);s.raid={version:1,hp:CONFIG.bossHp,maxHp:CONFIG.bossHp,rounds:[],config:{...CONFIG}};s.current={id:'training-tree-raid',type:'battle',name:'Raid'};s.ai={cards:[],board:Array(15).fill(null),bench:Array(6).fill(null),hand:[],draw:[],discard:[],artifacts:[],reserve:[]};return s;}
function bindRandom(b){b.random=()=>{b.raid.rng=(Math.imul(1664525,b.raid.rng)+1013904223)>>>0;return b.raid.rng/4294967296;};}
const create=G.createBattle;G.createBattle=function(s){const b=create(s);if(!b||!s.raid)return b;const c=s.raid.config;b.raid={phase:s.round,config:{...c},rng:(s.seed+s.battleSerial*997+s.round)>>>0,bossDamage:0,minionDamage:0,healed:0,nextRoot:c.rootFirst,nextHeal:c.healFirst,roots:[],channel:null,replenished:false,spawnSerial:2};bindRandom(b);const boss=b.units.find(u=>u.uid==='raid-tree');Object.assign(boss,{raidBoss:true,bodyRadius:30,x:215,y:180,hp:s.raid.hp,maxhp:s.raid.maxHp,atk:c.bossAtk,defense:c.bossDefense,rate:c.bossRate,range:c.bossRange,speed:0});for(const u of b.units.filter(u=>u.type===SPROUT))Object.assign(u,{hp:c.sproutHp,maxhp:c.sproutHp,atk:c.sproutAtk,defense:c.sproutDefense,rate:c.sproutRate,speed:c.sproutSpeed});b.recordStats=()=>G.recordBattleStats(s,b);return b;};
function basic(b,boss,target){const c=b.raid.config;const windup=c.attackWindup??.45,travel=c.attackTravel??.22;(b.raid.attacks??=[]).push({target:target.uid,start:b.time,launch:b.time+windup,impact:b.time+windup+travel,windup,travel});}
function actions(b,dt,pending){const r=b.raid,c=r.config,boss=b.units.find(u=>u.raidBoss),allies=b.units.filter(u=>u.hp>0&&!u.side);if(!boss||boss.hp<=0||!allies.length)return;
 for(const a of r.attacks||[])if(b.time+1e-8>=a.impact){const target=allies.find(u=>u.uid===a.target);if(target){G.hit(b,boss,target,boss.atk*boss.commandAtk,pending,false);b.effects.push({kind:'raid-impact',x:target.x,y:target.y-22,life:.32,full:.32});}}r.attacks=(r.attacks||[]).filter(a=>a.impact>b.time+1e-8);
 if(r.phase>=3&&b.time>=r.nextRoot){const target=allies[Math.floor(b.random()*allies.length)];r.roots.push({x:target.x,y:target.y,at:b.time+c.rootWarning});r.nextRoot+=c.rootInterval;}
 for(const mark of r.roots.filter(v=>v.at<=b.time)){for(const u of allies)if(Math.hypot(u.x-mark.x,u.y-mark.y)<=c.rootRadius){G.hit(b,boss,u,c.rootDamage,pending,true);pending.push({target:u,status:{root:c.rootDuration}});}b.effects.push({kind:'area',shape:'circle',x:mark.x,y:mark.y,r:c.rootRadius,color:'#c788df',life:.45,full:.45});}r.roots=r.roots.filter(v=>v.at>b.time);
 if(r.phase>=4&&!r.channel&&b.time>=r.nextHeal){r.nextHeal+=c.healInterval;const contributors=b.units.filter(u=>u.type===SPROUT&&u.hp>0).map(u=>u.uid);if(contributors.length&&r.healed<c.healCap)r.channel={end:b.time+c.healChannel,contributors};}
 // Channel suppresses basic attacks during its window; dead contributors are checked after all simultaneous damage.
 if(r.channel)boss.cooldown=Math.max(boss.cooldown,dt+.05);
}
function sprout(b,pos){const c=b.raid.config,t=G.BY[SPROUT];return {uid:'raid-sprout-'+b.raid.spawnSerial++,type:SPROUT,level:0,side:1,x:pos,y:225,hp:c.sproutHp,maxhp:c.sproutHp,atk:c.sproutAtk,defense:c.sproutDefense,rate:c.sproutRate,speed:c.sproutSpeed,crit:0,range:34,armor:0,skill:1,charge:0,progress:0,cooldown:.3,hits:0,received:0,flash:0,dead:false};}
function resolve(b){const r=b.raid,c=r.config,boss=b.units.find(u=>u.raidBoss);boss.x=215;boss.y=180;
 // Victory takes priority over allied elimination, time expiry, healing and replenishment.
 if(boss.hp<=0){b.result='win';return;}
 if(!b.units.some(u=>!u.side&&u.hp>0)){b.result='loss';return;}
 if(r.channel&&b.time+1e-8>=r.channel.end){const n=r.channel.contributors.filter(id=>b.units.some(u=>u.uid===id&&u.hp>0)).length,heal=Math.max(0,Math.min(n*c.healPerSprout,c.healCap-r.healed,boss.maxhp-boss.hp));boss.hp+=heal;r.healed+=heal;r.channel=null;if(heal)b.effects.push({kind:'heal',x:boss.x,y:boss.y,color:'#98ee9f',life:.7,full:.7});}
 if(r.phase===5&&!r.replenished&&b.time>=c.replenishAt){r.replenished=true;let n=b.units.filter(u=>u.type===SPROUT&&u.hp>0).length;for(;n<c.maxSprouts;n++)b.units.push(sprout(b,n===0?140:290));}
}
const record=G.recordBattleStats;G.recordBattleStats=function(s,b){const recorded=record(s,b);if(s.raid&&b?.raid&&recorded){s.raid.hp=root.JourneyRaid.health(b);const report={round:s.round,bossDamage:b.raid.bossDamage,minionDamage:b.raid.minionDamage,healed:b.raid.healed,remaining:s.raid.hp,seconds:b.time,units:b.units.filter(u=>!u.side).map(u=>({uid:u.uid,type:u.type,bossDamage:u.bossDamage||0,minionDamage:u.minionDamage||0}))};s.raid.rounds.push(report);}return recorded;};
const finish=G.finish;G.finish=function(s,result){if(!s.raid)return finish(s,result);if(s.phase!=='battle'||!['win','loss'].includes(result))return false;if(!s.handFrozen){s.discard.push(...s.hand);s.hand=[];}s.roundResult=result;if(result==='win'){s.score[0]=1;s.phase='victory';}else{s.score[1]++;s.phase=s.score[1]>=s.raid.config.maxLosses?'defeat':'roundResult';}return true;};
// Persist unit references (zones/targeted effects) and PRNG state, not JS closures.
function snapshot(s,b){const active=s.phase==='battle'?b:null,units=active?.units||[];return JSON.stringify({version:1,state:s,battle:active},function(key,value){if(typeof value==='function')return undefined;if(value&&units.includes(value)&&this!==units)return {$raidUnit:value.uid};return value;});}
function restore(raw){const data=JSON.parse(raw);if(data.version!==1||!data.state?.raid||data.state.raid.version!==1||!['prep','battle','roundResult','encounterWin','actComplete','tree','victory','defeat'].includes(data.state.phase))throw Error('Invalid raid save');const s=data.state,b=data.battle;if(s.phase==='battle'&&!b?.raid)throw Error('Missing battle');if(b){const walk=o=>{if(!o||typeof o!=='object')return o;if(o.$raidUnit)return b.units.find(u=>u.uid===o.$raidUnit);for(const k of Object.keys(o))o[k]=walk(o[k]);return o;};walk(b);const boss=b.units.find(u=>u.raidBoss);if(boss){boss.y=180;boss.bodyRadius=30;if(boss.motion)boss.motion=null;}delete b.raid.config.roundSeconds;bindRandom(b);b.recordStats=()=>G.recordBattleStats(s,b);}return {state:s,battle:b};}
root.JourneyRaid={CONFIG,TREE,SPROUT,health:b=>b.units.find(u=>u.raidBoss).hp,formation,build,basic,actions,resolve,snapshot,restore};
})(typeof globalThis!=='undefined'?globalThis:this);
